CREATE OR REPLACE FUNCTION harness_shared.capture_substrate_outbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    DECLARE
      v_op      TEXT;
      v_rec     RECORD;
      v_origin  TEXT;
      v_key     TEXT;
      v_row     JSONB;
      v_ws      TEXT;
      v_slug    TEXT;
      v_keycol  TEXT := TG_ARGV[0];
    BEGIN
      IF (TG_OP = 'DELETE') THEN
        v_op := 'del';
        v_rec := OLD;
      ELSE
        v_op := 'put';
        v_rec := NEW;
      END IF;

      v_row := to_jsonb(v_rec);
      v_origin := v_row ->> 'origin';

      -- Echo-loop guard: skip remote-origin writes (the projection's own writes).
      IF COALESCE(v_origin, 'local') <> 'local' THEN
        RETURN v_rec;
      END IF;

      v_key  := v_row ->> v_keycol;
      v_ws   := COALESCE(v_row ->> 'workspace_id', '');
      v_slug := v_row ->> 'harness_slug';

      INSERT INTO harness_shared.substrate_outbox
        (workspace_id, harness_slug, table_name, op, key, row, ts)
      VALUES
        (v_ws, v_slug, TG_TABLE_NAME, v_op, v_key, v_row,
         (extract(epoch from now()) * 1000)::bigint);

      PERFORM pg_notify('substrate_outbox', v_ws || '::' || v_slug);

      RETURN v_rec;
    END;
    $$;

CREATE OR REPLACE FUNCTION harness_shared.compute_needs_design(p_title text, p_summary text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  haystack TEXT := lower(coalesce(p_title, '') || ' ' || coalesce(p_summary, ''));
BEGIN
  -- Mirrors apps/operator/lib/design-phase.ts keyword regexes. Kept
  -- intentionally simple; if a writer needs richer detection it can
  -- compute needs_design in TS and pass it explicitly.
  RETURN haystack ~ E'\\m(ui|ux|design|layout|page|screen|view|component|panel|modal|drawer|button|form|chart|color|theme|font|icon|navigation|menu|toolbar|sidebar|header|footer|landing|onboarding)\\M'
      OR haystack ~ E'\\m(label|copy|wording|message|placeholder|tooltip|empty[\\s-]?state|error[\\s-]?message|prompt[\\s-]?text|microcopy|i18n|translation)\\M'
      OR haystack ~ E'\\m(route|page|url|slug|navigation|navlink|tab|breadcrumb|deep[\\s-]?link)\\M'
      OR haystack ~ E'\\m(icon|iconography|illustration|graphic|svg|image|avatar|logo|emoji)\\M';
END;
$$;

CREATE OR REPLACE FUNCTION harness_shared.emit_change_notify() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  payload jsonb;
  ws_id   text;
  q_name  text;
BEGIN
  ws_id := current_setting('papercusp.workspace_id', true);
  q_name := TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME || '.changed';

  payload := jsonb_build_object(
    'name', q_name,
    'args', jsonb_build_object(
      'workspace_id', ws_id,
      'op',           TG_OP
    )
  );

  PERFORM pg_notify('sync_invalidate', payload::text);

  -- For DELETE triggers, the legal return is OLD. For INSERT/UPDATE,
  -- return NEW. The trigger is declared AFTER so the value is unused,
  -- but PostgreSQL still requires a structurally-valid return.
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION harness_shared.fill_needs_design() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.needs_design IS NULL OR NEW.needs_design = FALSE THEN
    NEW.needs_design := harness_shared.compute_needs_design(NEW.title, NEW.summary);
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION harness_shared.fill_workspace_id_from_projects() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
      IF NEW.workspace_id IS NULL OR NEW.workspace_id = '' THEN
        SELECT workspace_id INTO NEW.workspace_id
          FROM harness_shared.projects WHERE slug = NEW.harness_slug LIMIT 1;
        IF NEW.workspace_id IS NULL OR NEW.workspace_id = '' THEN
          NEW.workspace_id := 'default';
        END IF;
      END IF;
      RETURN NEW;
    END;
    $$;

