CREATE OR REPLACE FUNCTION harness_shared.prune_test_runs(keep_per_file_branch integer DEFAULT 50) RETURNS integer
    LANGUAGE plpgsql
    AS $$
    DECLARE
      deleted_count INTEGER;
    BEGIN
      WITH ranked AS (
        SELECT id,
               ROW_NUMBER() OVER (
                 PARTITION BY file_path, COALESCE(branch, '__null__')
                 ORDER BY finished_at DESC NULLS LAST, id DESC
               ) AS rn
          FROM harness_shared.test_runs
      )
      DELETE FROM harness_shared.test_runs
       WHERE id IN (SELECT id FROM ranked WHERE rn > keep_per_file_branch);
      GET DIAGNOSTICS deleted_count = ROW_COUNT;
      RETURN deleted_count;
    END;
    $$;

