CREATE OR REPLACE VIEW harness_shared.tool_invocations_artifacts AS
 SELECT id,
    workspace_id,
    harness_slug,
    plugin_name,
    tool_name,
    role,
    feature_id,
    chunk_id,
    run_id,
    spawn_id,
    invoked_at,
    duration_ms,
    status,
    output_ref,
    output_size
   FROM harness_shared.tool_invocations
  WHERE ((output_ref IS NOT NULL) AND (output_ref <> ''::text) AND (status = 'ok'::text));

COMMENT ON VIEW harness_shared.tool_invocations_artifacts IS 'Successful tool calls that wrote a scratch-dir output (Pack, Diff,
   Repomix). Feeds the Intel panel''s Pack + Diff sub-tabs.';

