    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE harness_shared.tool_invocations_id_seq OWNED BY harness_shared.tool_invocations.id;

CREATE OR REPLACE VIEW harness_shared.tool_invocations_spawn_tree AS
 WITH RECURSIVE chain AS (
         SELECT tool_invocations.id,
            tool_invocations.workspace_id,
            tool_invocations.harness_slug,
            tool_invocations.plugin_name,
            tool_invocations.tool_name,
            tool_invocations.role,
            tool_invocations.feature_id,
            tool_invocations.chunk_id,
            tool_invocations.run_id,
            tool_invocations.spawn_id,
            tool_invocations.parent_spawn_id,
            tool_invocations.window_key,
            tool_invocations.invoked_at,
            tool_invocations.duration_ms,
            tool_invocations.status,
            tool_invocations.output_ref,
            tool_invocations.output_size,
            tool_invocations.error_message,
            0 AS depth,
            tool_invocations.spawn_id AS root_spawn_id
           FROM harness_shared.tool_invocations
          WHERE ((tool_invocations.parent_spawn_id IS NULL) OR (tool_invocations.parent_spawn_id = ''::text))
        UNION ALL
         SELECT t.id,
            t.workspace_id,
            t.harness_slug,
            t.plugin_name,
            t.tool_name,
            t.role,
            t.feature_id,
            t.chunk_id,
            t.run_id,
            t.spawn_id,
            t.parent_spawn_id,
            t.window_key,
            t.invoked_at,
            t.duration_ms,
            t.status,
            t.output_ref,
            t.output_size,
            t.error_message,
            (c.depth + 1),
            c.root_spawn_id
           FROM (harness_shared.tool_invocations t
             JOIN chain c ON (((t.parent_spawn_id = c.spawn_id) AND (t.workspace_id = c.workspace_id) AND (c.depth < 16))))
        )
 SELECT id,
    workspace_id,
    harness_slug,
    plugin_name,
    tool_name,
    role,
    feature_id,
    chunk_id,
    run_id,
    spawn_id,
    parent_spawn_id,
    window_key,
    invoked_at,
    duration_ms,
    status,
    output_ref,
    output_size,
    error_message,
    depth,
    root_spawn_id
   FROM chain;

COMMENT ON VIEW harness_shared.tool_invocations_spawn_tree IS 'Recursive lineage over tool_invocations.parent_spawn_id. depth=0 for
   roots; depth>0 for spawn-of-spawn children (Phase 9). RLS inherits from
   harness_shared.tool_invocations.';

